function Footer({ english }) { const footer = SITE.footer; const links = [{ key: 'partner', href: footer.partner.url, icon: footer.partner.logoPath ? <img src={footer.partner.logoPath} alt=""/> : '◉', name: footer.partner.name, detail: footer.partner.url.replace(/^https?:\/\//, '').replace(/\/$/, '') }, { key: 'github', href: footer.github, icon: <i className="ti ti-brand-github" aria-hidden="true"/>, name: 'GitHub', detail: footer.githubLabel }, { key: 'x', href: footer.x, icon: <i className="ti ti-brand-x" aria-hidden="true"/>, name: 'X', detail: footer.x.replace(/^https?:\/\//, '').replace(/\/$/, '') }, { key: 'xiaohongshu', href: footer.xiaohongshu, icon: <span className="footer-social-glyph">RED</span>, name: english ? footer.xiaohongshuNameEn : footer.xiaohongshuName, detail: english ? footer.xiaohongshuDetailEn : footer.xiaohongshuDetail }, { key: 'email', href: footer.email, icon: <i className="ti ti-mail" aria-hidden="true"/>, name: 'Email', detail: footer.email.replace(/^mailto:/, '') }, { key: 'contribution', href: footer.contribution, icon: <i className="ti ti-pencil-plus" aria-hidden="true"/>, name: english ? 'Term suggestions' : '术语投稿', detail: english ? 'Submit a suggestion' : '提交建议' }].filter((item) => item.href); return <footer className="site-footer"><div className="site-footer-shell"><div className="site-footer-content"><div className="footer-wordmark" aria-hidden="true">{footer.wordmark}</div><nav className="footer-socials" aria-label="Links and contribution">{links.map((item) => <a className={`footer-social-link ${item.key === 'contribution' ? 'footer-contribute-card' : ''}`} href={item.href} target={item.href.startsWith('http') ? '_blank' : undefined} rel={item.href.startsWith('http') ? 'noreferrer' : undefined} key={item.key}><span className="footer-social-icon">{item.icon}</span><span className="footer-social-copy"><strong>{item.name}</strong><small>{item.detail}</small></span><i className="ti ti-arrow-up-right footer-social-arrow" aria-hidden="true"/></a>)}</nav></div></div></footer>; }

function AuthDialog({ english, auth, onClose }) {
  const [mode, setMode] = useState('sign-in');
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [busy, setBusy] = useState(false);
  const submit = async (event) => {
    event.preventDefault();
    setBusy(true);
    try {
      if (mode === 'sign-up') await auth.signUp(name.trim() || email.split('@')[0], email.trim(), password);
      else await auth.signIn(email.trim(), password);
      onClose();
    } catch {}
    finally { setBusy(false); }
  };
  const signOut = async () => { setBusy(true); try { await auth.signOut(); onClose(); } catch {} finally { setBusy(false); } };
  return <div className="header-popover-backdrop" onClick={onClose}><section className="account-dialog" role="dialog" aria-modal="true" aria-labelledby="account-title" onClick={(event) => event.stopPropagation()}><button className="popover-close" aria-label={english ? 'Close account dialog' : '关闭账号窗口'} onClick={onClose}>{icons.close}</button>{auth.session ? <><span className="eyebrow">{english ? 'Account' : '账号'}</span><h2 id="account-title">{auth.session.user?.name || auth.session.user?.email}</h2><p>{english ? 'Favorites and practice history are now syncing with the local server.' : '收藏和练习记录正在与本地后端同步。'}</p><button type="button" className="demo-primary account-submit" disabled={busy} onClick={signOut}>{busy ? (english ? 'Signing out…' : '正在退出…') : (english ? 'Sign out' : '退出登录')}</button></> : <><span className="eyebrow">{mode === 'sign-up' ? (english ? 'Create account' : '注册账号') : (english ? 'Sign in' : '登录')}</span><h2 id="account-title">{english ? 'Sync your learning progress.' : '同步你的学习进度。'}</h2><p>{english ? 'You can still browse anonymously. Sign in to keep favorites and practice history on this server.' : '不登录也可以继续浏览；登录后收藏和练习记录会保存到本地后端。'}</p><form className="account-form" onSubmit={submit}>{mode === 'sign-up' && <label>{english ? 'Name' : '昵称'}<input value={name} onChange={(event) => setName(event.target.value)} autoComplete="name" /></label>}<label>{english ? 'Email' : '邮箱'}<input type="email" required value={email} onChange={(event) => setEmail(event.target.value)} autoComplete="email" /></label><label>{english ? 'Password' : '密码'}<input type="password" required minLength={8} value={password} onChange={(event) => setPassword(event.target.value)} autoComplete={mode === 'sign-up' ? 'new-password' : 'current-password'} /></label>{auth.error && <p className="account-error" role="alert">{auth.error}</p>}<button type="submit" className="demo-primary account-submit" disabled={busy}>{busy ? (english ? 'Working…' : '处理中…') : mode === 'sign-up' ? (english ? 'Create account' : '注册并登录') : (english ? 'Sign in' : '登录')}</button></form><button type="button" className="account-mode-toggle" onClick={() => { setMode((value) => value === 'sign-in' ? 'sign-up' : 'sign-in'); auth.setError(''); }}>{mode === 'sign-up' ? (english ? 'Already have an account? Sign in' : '已有账号？登录') : (english ? 'Need an account? Sign up' : '还没有账号？注册')}</button></>}</section></div>;
}

function GitCardVisual({ id, english }) {
  const zh = !english;
  const text = {
    git: zh ? ['项目历史', '初始化项目', '构建首页', '修复按钮'] : ['Project history', 'Initialize project', 'Build homepage', 'Fix button'],
    commit: zh ? ['当前代码', '保存为一个版本', '已保存版本'] : ['Current code', 'Save as a version', 'Saved version'],
    branch: zh ? ['主版本', '保持稳定', '新功能', '独立修改', '分支从这里开始'] : ['Main version', 'Stays stable', 'New feature', 'Changes independently', 'Branches here'],
    merge: zh ? ['主版本', '新功能', '主版本已更新', '两边的改动已合并'] : ['main version', 'New Features', 'The main version has been updated', 'The changes on both sides have been put together'],
    pull: zh ? ['GitHub 远程', '本地版本', '拉取并整合提交'] : ['GitHub remote', 'Local version', 'Fetch and integrate commits'],
    push: zh ? ['本地代码', '上传提交', 'GitHub'] : ['Local changes', 'Upload commits', 'GitHub'],
    clone: zh ? ['GitHub 项目', '创建本地副本', '本地文件夹'] : ['GitHub project', 'Create a local copy', 'Local folder'],
    pr: zh ? ['新功能分支', '更新首页导航', '3 个文件已修改', '说清楚改动', '通过检查', '可以合并到主版本'] : ['New feature branch', 'Update homepage navigation', '3 files have changed', 'Explain clearly', 'Pass the check', 'Can be merged into the main version'],
    worktree: zh ? ['同一份 Git 历史', '项目主版本', '新功能版本'] : ['The same Git history', 'Project master version', 'New feature version'],
  };
  const frame = (children, className) => <div className={`catalog-mini-demo catalog-mini-diagram source-git-card-preview ${className || ''}`} aria-hidden="true"><div className="catalog-mini-mount">{children}</div></div>;
  if (id === 'git') return frame(<div className="git-mini git-history"><small>{text.git[0]}</small><div className="git-line"><span/><span/><b/><span/></div><div className="git-labels"><i>{text.git[1]}</i><i>{text.git[2]}</i><i>{text.git[3]}</i></div></div>, 'git-history-preview');
  if (id === 'commit') return frame(<div className="git-mini git-commit"><div><b>▤</b><strong>{text.commit[0]}</strong></div><i>Save as a version<br/>commit　→</i><div className="saved"><b>✓</b><strong>{text.commit[2]}</strong></div></div>, 'git-commit-preview');
  if (id === 'branch') return frame(<div className="git-mini git-branch"><div><b>{text.branch[0]}</b><small>{text.branch[1]}</small><span/><span/><span/></div><i>{text.branch[4]}</i><div className="feature"><b>{text.branch[2]}</b><small>{text.branch[3]}</small><span/><span/></div></div>, 'git-branch-preview');
  if (id === 'merge') return frame(<div className="git-mini git-merge"><div className="merge-lanes"><b>{text.merge[0]}</b><span/><span/><b>{text.merge[1]}</b><span/><span/></div><div className="merge-note"><strong>{text.merge[2]}</strong><small>{text.merge[3]}</small></div></div>, 'git-merge-preview');
  if (id === 'pull') return frame(<div className="git-mini git-transfer"><div><b>•••</b><strong>{text.pull[0]}</strong></div><i>Fetch and integrate commits<br/>pull　→</i><div><b>▱</b><strong>{text.pull[1]}</strong></div></div>, 'git-pull-preview');
  if (id === 'push') return frame(<div className="git-mini git-transfer"><div><b>▱</b><strong>{text.push[0]}</strong></div><i>Upload commits<br/>push　→</i><div><b>•••</b><strong>{text.push[2]}</strong></div></div>, 'git-push-preview');
  if (id === 'clone') return frame(<div className="git-mini git-transfer"><div><b>•••</b><strong>{text.clone[0]}</strong></div><i>Create a local copy<br/>clone　→</i><div><b>□</b><strong>{text.clone[2]}</strong></div></div>, 'git-clone-preview');
  if (id === 'pull-request') return frame(<div className="git-mini git-pr"><div><b>{text.pr[0]}</b><strong>{text.pr[1]}</strong><small>{text.pr[2]}</small></div><i>Send to others for review<br/>Pull Request　→</i><div><span>✓ {text.pr[3]}</span><span>✓ {text.pr[4]}</span><b>{text.pr[5]}</b></div></div>, 'git-pr-preview');
  if (id === 'worktree') return frame(<div className="git-mini git-worktree"><small>{text.worktree[0]}</small><div><span>□ {text.worktree[1]}</span><span>□ {text.worktree[2]}</span></div></div>, 'git-worktree-preview');
  if (['stash', 'gitignore', 'diff'].includes(id)) return frame(<div className={`git-mini git-empty git-empty-${id}`}><span/><span/><span/></div>, `git-${id}-preview`);
  return null;
}

