function TermCard({ item, favorite, onFavorite, english, heightByTopic }) { const term = localizeTerm(itemFields(item), english); const title = splitLocalizedTitle(term.name, english); const topicHeights = heightByTopic?.[topicForItem(term.id)[0]]; const fallbackHeights = english ? catalogCardHeights : catalogCardHeightsZh; const height = topicHeights?.[term.id] ?? fallbackHeights[term.id]; const favoriteLabel = favorite ? 'Remove from favorites' : 'Add to favorites'; return <article className="term-card card" data-id={term.id} style={height ? { height: `${height}px` } : undefined}><div className="term-card-head card-head"><SmartLink className="card-title-link card-title-group" href={`${english ? '/en' : ''}/${term.id}`} aria-label={term.name}><h3>{title.local}{title.translated && <span>{title.translated}</span>}</h3></SmartLink><button className={`favorite-button ${favorite ? 'is-favorite' : ''}`} aria-label={favoriteLabel} aria-pressed={favorite} title={favoriteLabel} onClick={() => onFavorite(term.id)}>{catalogStar}</button></div><div className="card-tagline card-quote">{term.description}</div><MiniVisual type={term.visual} id={term.id} english={english}/></article>; }

function Survey({ onClose, onAnswer, english }) { const options = [{ key: 'Bilibili', label: english ? 'Bilibili' : '哔哩哔哩' }, { key: 'Douyin', label: english ? 'Douyin' : '抖音' }, { key: 'Xiaohongshu', label: english ? 'Xiaohongshu' : '小红书' }, { key: 'X', label: 'X' }, { key: 'GitHub', label: 'GitHub' }, { key: 'WeChat Channels', label: english ? 'WeChat Channels' : '视频号' }, { key: 'Other', label: english ? 'Other' : '其他' }]; const [answered, setAnswered] = useState(null); const choose = (key) => { if (answered !== null) return; setAnswered(key); onAnswer(key); }; return <section className="source-survey" role="dialog" aria-labelledby="source-survey-title" aria-describedby="source-survey-description"><div className="source-survey-card"><header className="source-survey-header"><div><p className="source-survey-kicker">{english ? 'One quick question' : '一个小问题'}</p><p className="source-survey-title" id="source-survey-title">{english ? 'Where did you first hear about VibeHub?' : '你是在哪里了解到 VibeHub 的？'}</p><p className="source-survey-description" id="source-survey-description">{english ? 'Choose the closest match.' : '选择最接近的渠道即可。'}</p></div><button className="source-survey-close" type="button" aria-label={english ? 'Skip this question' : '跳过这个问题'} onClick={onClose}>{icons.close}</button></header><div className="source-survey-options" aria-busy={answered !== null ? 'true' : undefined}>{options.map(({ key, label }) => <button className="source-survey-option" type="button" key={key} disabled={answered !== null} onClick={() => choose(key)}><span className="source-survey-option-mark" aria-hidden="true">{surveyMarks[key]}</span><span>{label}</span></button>)}</div><p className="source-survey-error" aria-live="polite"/></div></section>; }

function GlobalSurvey() { const route = useRoute(); const routeTermId = route.clean.replace(/^\//, '').split('/')[0]; const isTermSurface = route.clean === '/' || route.clean.startsWith('/topics/') || (route.clean.split('/').length === 2 && itemMap.has(routeTermId)); const [open, setOpen] = useState(() => isTermSurface && !readSurveySeen()); useEffect(() => { setOpen(isTermSurface && !readSurveySeen()); }, [isTermSurface, route.clean]); if (!open || !isTermSurface) return null; const close = () => { setOpen(false); markSurveySeen(); }; const answer = (key) => { markSurveySeen(); window.setTimeout(() => setOpen(false), 1000); }; return createPortal(<div className="vh-html-replica"><Survey onClose={close} onAnswer={answer} english={route.english}/></div>, document.body); }

function TermsPage({ english, query, setQuery, favorites, setFavorites }) {
  usePageTitle(`${english ? 'VibeHub | Vibe Coding Terms' : 'VibeHub｜Vibe Coding 术语图鉴 · 用大白话找准前端、后端、AI 术语'}`);
  const [category, setCategory] = useState('frontend'); const [surveyOpen, setSurveyOpen] = useState(() => !readSurveySeen()); const prefix = english ? '/en' : ''; const active = topicById.get(category) || topicMeta[0];
  const sections = category === 'favorites' ? [{ name: english ? 'Favorites' : '收藏', count: favorites.length, items: allItems.filter((item) => favorites.includes(itemFields(item).id)) }] : catalogData[active[3]];
  const visible = useMemo(() => sections.map((section) => ({ ...section, items: section.items.filter((item) => { const { name, description } = itemFields(item); return `${name} ${description}`.toLowerCase().includes(query.toLowerCase()); }) })).filter((section) => section.items.length || !query), [sections, query]);
  const toggleFavorite = (id) => setFavorites((current) => current.includes(id) ? current.filter((value) => value !== id) : [...current, id]); const categories = [...topicMeta.map(([id, label, , , zhLabel]) => ({ id, label: english ? label : zhLabel, count: topicCounts[id] })), { id: 'favorites', label: english ? 'Favorites' : '收藏', count: favorites.length }]; const closeSurvey = () => { setSurveyOpen(false); markSurveySeen(); };
  return <><main id="top" className="terms-page"><section className="category-strip" aria-label="Term categories">{categories.map((item) => <button key={item.id} className={category === item.id ? 'category-active' : ''} onClick={() => { setCategory(item.id); setQuery(''); }}>{item.label}<span>{item.count}</span></button>)}</section><div className="page-layout"><aside className="section-nav" aria-label="Sections">{sections.map((section, index) => <a key={section.name} className={index === 0 ? 'section-active' : ''} href={`#${slugify(section.name)}`}>{sectionLabel(section, english)}</a>)}</aside><div className="content-area" id="terms"><div className="content-heading"><h1>{category === 'favorites' ? (english ? 'Favorite Terms' : '收藏术语') : (english ? active[2] : active[5])}</h1>{query && <span className="search-result">{visible.reduce((sum, section) => sum + section.items.length, 0)} {english ? 'matches' : '个匹配结果'}</span>}</div>{visible.length ? visible.map((section) => <section className={`term-section section-${slugify(section.name)}`} key={section.name} id={slugify(section.name)}><div className="section-heading"><h2>{sectionLabel(section, english)}</h2><span>{section.items.length} {english ? 'entries' : '个条目'}</span></div><div className="term-grid">{section.items.map((item) => <TermCard key={itemFields(item).id} item={item} favorite={favorites.includes(itemFields(item).id)} onFavorite={toggleFavorite} english={english} heightByTopic={catalogCardHeightsByTopic[english ? 'en' : 'zh']}/>)}</div></section>) : <div className="empty-state"><div>{icons.search}</div><h2>{english ? 'No terms found' : '没有找到术语'}</h2><p>{english ? 'Try a different search or category.' : '换一个搜索词或分类试试。'}</p></div>}</div></div></main>{surveyOpen && <Survey onClose={closeSurvey} english={english}/>}</>;
}

function CopyButton({ text, english, className = '' }) { const [copied, setCopied] = useState(false); const copy = async () => { try { await navigator.clipboard.writeText(text); } catch {} setCopied(true); window.setTimeout(() => setCopied(false), 1400); }; return <button className={`copy-button ${className} ${copied ? 'is-copied' : ''}`.trim()} onClick={copy}><span className="copy-labels"><span className="copy-label-default">{english ? 'Copy as Markdown' : '复制为 Markdown'}</span><span className="copy-label-success">{english ? 'Copied' : '已复制'}</span></span>{icons.copy}</button>; }
function PronunciationButton({ term, english }) { const [spoken, setSpoken] = useState(false); const speak = () => { if ('speechSynthesis' in window) { window.speechSynthesis.cancel(); const utterance = new SpeechSynthesisUtterance(term.name); utterance.lang = english ? 'en-US' : 'zh-CN'; window.speechSynthesis.speak(utterance); } setSpoken(true); window.setTimeout(() => setSpoken(false), 1400); }; return <button className="pronunciation-button" aria-label={english ? `Hear the pronunciation of ${term.name}` : `听${term.name}的发音`} onClick={speak}>{spoken ? '✓' : icons.speaker}</button>; }
function DemoShell({ children, title = 'Try it', className = '' }) { return <section className={`demo-shell ${className}`.trim()}><div className="demo-shell-head"><span>{title}</span><small>Interactive demo</small></div><div className="demo-content">{children}</div></section>; }

function AdvancedDemo({ term, english }) {
  const id = term.id;
  const [selected, setSelected] = useState(''); const [count, setCount] = useState(1); const [file, setFile] = useState(''); const [slide, setSlide] = useState(0); const [message, setMessage] = useState(''); const [messages, setMessages] = useState([english ? 'Ask about a term to start.' : '输入一个术语开始提问。']); const [items, setItems] = useState(['Research', 'Prototype', 'Review']); const [selectedItems, setSelectedItems] = useState([]); const [terminal, setTerminal] = useState('');
  if (id === 'select' || id === 'auto-complete' || id === 'cascader' || id === 'tree-select') return <DemoShell title={english ? 'Choose a value' : '选择一个值'}><label className="demo-label">{english ? 'Project' : '项目'}<select className="demo-input" value={selected} onChange={(event) => setSelected(event.target.value)}><option value="">{english ? 'Choose one…' : '请选择…'}</option><option>Design system</option><option>Product launch</option><option>Research notes</option></select></label>{selected && <div className="demo-feedback success">✓ {selected} {english ? 'selected' : '已选择'}</div>}</DemoShell>;
  if (id === 'input-number' || id === 'number-input') return <DemoShell title={english ? 'Number input' : '数字输入'}><div className="number-control"><button className="demo-secondary" onClick={() => setCount((value) => Math.max(1, value - 1))}>−</button><output>{count}</output><button className="demo-secondary" onClick={() => setCount((value) => value + 1)}>＋</button></div><p className="demo-hint">{english ? 'Quantity must stay at or above 1.' : '数量不能小于 1。'}</p></DemoShell>;
  if (id === 'date-picker' || id === 'time-picker') return <DemoShell title={english ? 'Pick a value' : '选择时间'}><label className="demo-label">{id === 'date-picker' ? (english ? 'Date' : '日期') : (english ? 'Time' : '时间')}<input className="demo-input" type={id === 'date-picker' ? 'date' : 'time'} value={selected} onChange={(event) => setSelected(event.target.value)}/></label>{selected && <div className="demo-feedback success">✓ {selected}</div>}</DemoShell>;
  if (id === 'upload') return <DemoShell title={english ? 'Upload with progress' : '带进度的上传'}><label className="upload-drop"><input type="file" accept="image/png,image/jpeg" onChange={(event) => setFile(event.target.files?.[0]?.name || '')}/><strong>⬆ {english ? 'Click or drag a file here' : '点击或拖拽文件到这里'}</strong><small>JPG / PNG · 10 MB max</small></label>{file && <div className="file-row"><span>▣ {file}</span><b>100%</b></div>}</DemoShell>;
  if (id === 'collapse' || id === 'faq') return <DemoShell title={english ? 'Expand details' : '展开详情'}><div className="accordion-demo">{['What does this term solve?', 'When should I use it?', 'How do I verify it?'].map((question) => <details key={question}><summary>{question}<span>＋</span></summary><p>{english ? 'Keep the answer close to the question and make the next action clear.' : '把答案放在问题旁边，让下一步操作清晰可见。'}</p></details>)}</div></DemoShell>;
  if (id === 'carousel') { const slides = english ? ['A clear first frame', 'A focused second frame', 'A helpful last frame'] : ['清晰的第一帧', '聚焦的第二帧', '有帮助的最后一帧']; return <DemoShell title={english ? 'Carousel' : '走马灯'}><div className="carousel-demo"><button className="demo-secondary" onClick={() => setSlide((value) => (value + slides.length - 1) % slides.length)}>←</button><strong>{slides[slide]}</strong><button className="demo-secondary" onClick={() => setSlide((value) => (value + 1) % slides.length)}>→</button></div><div className="carousel-dots">{slides.map((_, index) => <i className={index === slide ? 'active' : ''} key={index}/>)}</div></DemoShell>; }
  if (id === 'table' || id === 'chart' || id === 'statistic') return <DemoShell title={english ? 'Readable data' : '可读的数据'}><div className="data-table"><div><b>{english ? 'Item' : '条目'}</b><b>{english ? 'Status' : '状态'}</b><b>{english ? 'Value' : '数值'}</b></div>{[['Orders', 'Complete', '12,846'], ['Revenue', 'In progress', '¥86.4K'], ['Refunds', 'Review', '2.1%']].map((row) => <div key={row[0]}>{row.map((cell) => <span key={cell}>{cell}</span>)}</div>)}</div></DemoShell>;
  if (id === 'list') return <DemoShell title={english ? 'Add to a list' : '添加到列表'}><div className="demo-list">{items.map((item) => <button className={selectedItems.includes(item) ? 'selected' : ''} key={item} onClick={() => setSelectedItems((value) => value.includes(item) ? value.filter((entry) => entry !== item) : [...value, item])}>{item}<span>{selectedItems.includes(item) ? '✓' : '＋'}</span></button>)}</div><button className="demo-primary" onClick={() => setItems((value) => [...value, `Task ${value.length + 1}`])}>{english ? 'Add item' : '新增条目'}</button>{selectedItems.length > 0 && <div className="demo-feedback success">✓ {selectedItems.length} {english ? 'selected' : '项已选择'}</div>}</DemoShell>;
  if (id === 'tree') return <DemoShell title={english ? 'Expand a tree' : '展开树形结构'}><div className="tree-demo"><details open><summary>Project</summary><details><summary>src</summary><span>main.jsx</span><span>styles.css</span></details><details><summary>public</summary><span>assets</span></details></details></div></DemoShell>;
  if (id === 'chat-ui') return <DemoShell title={english ? 'Send a message' : '发送消息'}><div className="chat-demo">{messages.map((item, index) => <p key={`${item}-${index}`}>{item}</p>)}</div><div className="demo-row"><input className="demo-input" value={message} onChange={(event) => setMessage(event.target.value)} placeholder={english ? 'Ask about Button…' : '输入问题…'}/><button className="demo-primary" onClick={() => { if (!message.trim()) return; setMessages((value) => [...value, message.trim()]); setMessage(''); }}>{english ? 'Send' : '发送'}</button></div></DemoShell>;
  if (id === 'drag') return <DemoShell title={english ? 'Drag to reorder' : '拖拽排序'}><div className="drag-list">{items.map((item, index) => <div draggable onDragStart={(event) => event.dataTransfer.setData('text/plain', String(index))} onDragOver={(event) => event.preventDefault()} onDrop={(event) => { const from = Number(event.dataTransfer.getData('text/plain')); setItems((value) => { const next = [...value]; const [moved] = next.splice(from, 1); next.splice(index, 0, moved); return next; }); }} key={item}>⠿ {item}</div>)}</div></DemoShell>;
  if (id === 'terminal' || id === 'browser-devtools') return <DemoShell title={english ? 'Run a command' : '运行命令'}><div className="terminal-demo"><div>$ {terminal || 'type a command'}</div><pre>{terminal ? (terminal === 'help' ? 'build  test  deploy' : `command not found: ${terminal}`) : 'Try “help”'}</pre></div><div className="demo-row"><input className="demo-input" value={terminal} onChange={(event) => setTerminal(event.target.value)} placeholder="help"/><button className="demo-primary" onClick={() => setTerminal((value) => value.trim() || 'help')}>{english ? 'Run' : '运行'}</button></div></DemoShell>;
  return null;
}


