const gitStoryIds = ['git', 'commit', 'branch', 'merge', 'pull', 'push', 'clone', 'pull-request', 'worktree', 'stash', 'gitignore', 'diff'];
const gitStoryGroups = {
  git: [[0, 1], [2, 3], [11, 12]], commit: [[0, 1], [2, 3], [6, 7, 8]], branch: [[0, 1], [2], [3, 4]], merge: [[0, 1], [3, 4], [5]],
  pull: [[0, 1], [2, 3], [5, 6]], push: [[0, 1], [2, 3], [5, 6]], clone: [[0, 1], [2, 3], [5, 6]], 'pull-request': [[0, 1, 2], [3], [4, 6, 7, 8]],
  worktree: [[0, 1], [2], [3, 4]], stash: [[0, 1], [4, 5, 6], [8, 9, 10]], gitignore: [[0, 1], [2, 3], [4, 5, 6]], diff: [[0, 1, 2, 3], [5, 6, 7, 8]]
};
const gitStoryCommands = { git: 'git commit -m "Homepage update" && git push', commit: 'git commit -m "Complete homepage navigation"', branch: 'git switch -c feature/new-nav', merge: 'git merge feature/new-nav', pull: 'git pull', push: 'git push', clone: 'git clone <repository-url>', 'pull-request': 'Create a Pull Request on GitHub', worktree: 'git worktree add new-folder new-branch', stash: 'git stash push -m "The form is halfway done"', gitignore: 'echo .env >> .gitignore', diff: 'git diff' };
function GitStoryReferenceDemo({ term, english }) {
  const lines = referenceLines(term); const groups = gitStoryGroups[term.id] || [[0], [1], [2]]; const [active, setActive] = useState(0); const kind = ['branch', 'merge', 'worktree'].includes(term.id) ? 'graph' : term.id === 'diff' ? 'diff' : term.id === 'gitignore' ? 'ignore' : 'linear';
  const cards = groups.map((indexes, index) => ({ title: lines[indexes[0]] || term.name + ' ' + (index + 1), details: indexes.slice(1).map((lineIndex) => lines[lineIndex]).filter(Boolean) }));
  const next = () => setActive((value) => (value + 1) % cards.length);
  const card = (item, index, className = '') => <button className={"git-story-card " + className + (active === index ? ' active' : '')} onClick={() => setActive(index)} key={item.title + '-' + index}><small>{String(index + 1).padStart(2, '0')}</small><strong>{item.title}</strong>{item.details.map((detail, detailIndex) => <span key={detail + '-' + detailIndex}>{detail}</span>)}</button>;
  const graph = kind === 'graph' ? <div className={"git-story-graph-canvas graph-" + term.id}><div className="git-graph-lane git-graph-main"><div className="git-graph-label"><strong>{cards[0]?.title}</strong><span>{cards[0]?.details[0]}</span></div><div className="git-graph-line">{card(cards[0], 0, 'git-graph-dot')}{card(cards[1], 1, 'git-graph-dot')}</div></div><div className="git-graph-lane git-graph-feature"><div className="git-graph-label"><strong>{cards[2]?.title}</strong><span>{cards[2]?.details[0]}</span></div><div className="git-graph-line">{card(cards[2], 2, 'git-graph-dot')}</div></div><span className="git-graph-caption">{term.id === 'branch' ? (english ? 'Split here' : '从这里分叉') : term.id === 'worktree' ? (english ? 'Both folders share the same history' : '两个文件夹共享同一段历史') : (english ? 'Changes come together' : '变化汇合')}</span></div> : null;
  return <ReferenceStage className={"git-story git-story--" + term.id}><div className="git-story-main"><div className="git-story-head"><strong>{english ? term.name : termNameZh(term)}</strong><span>{english ? 'Try the example' : '试试这个示例'}</span></div>{kind === 'graph' ? graph : <div className={"git-story-track git-story-track-" + kind}>{cards.map((item, index) => <Fragment key={item.title + '-fragment-' + index}>{card(item, index)}{index < cards.length - 1 && <i>→</i>}</Fragment>)}</div>}</div><div className="git-story-answer"><div><code>{gitStoryCommands[term.id]}</code><p>{cards[active]?.details.join(' · ') || lines[groups[active]?.[0]] || term.description}</p></div><button className="demo-primary" onClick={next}>{active === cards.length - 1 ? (english ? 'Review again' : '重新查看') : (english ? 'Advance state' : '推进状态')} →</button></div></ReferenceStage>;
}

