  if (['tabs', 'segmented', 'menu', 'dropdown'].includes(id)) return <DemoShell title={english ? 'View switching' : '视图切换'}><div className="demo-tabs">{['Overview', 'Activity', 'Settings'].map((tab) => <button key={tab} className={selected === tab ? 'selected' : ''} onClick={() => setSelected(tab)}>{english ? tab : ({ Overview: '概览', Activity: '动态', Settings: '设置' }[tab])}</button>)}</div><div className="demo-panel"><strong>{selected}</strong><p>{english ? 'The active state is visible and the content updates in place.' : '当前状态清晰可见，内容在原地更新。'}</p></div></DemoShell>;
  if (['switch', 'checkbox', 'radio', 'disabled'].includes(id)) return <DemoShell title={english ? 'Selection controls' : '选择控件'}><label className="demo-switch"><input type="checkbox" checked={enabled} onChange={(event) => setEnabled(event.target.checked)}/><span>{enabled ? (english ? 'Enabled' : '已开启') : (english ? 'Disabled' : '已关闭')}</span></label><button className="demo-primary" disabled={!enabled} onClick={() => showNotice(english ? 'Action is available' : '操作可用')}>{english ? 'Continue' : '继续'}</button>{notice && <div className="demo-feedback success">✓ {notice}</div>}</DemoShell>;
  if (['slider', 'rate'].includes(id)) return <DemoShell title={english ? 'Value input' : '数值输入'}><label className="demo-label">{id === 'rate' ? (english ? 'Rating' : '评分') : (english ? 'Volume' : '音量')}<input type="range" min="0" max="5" value={rating} onChange={(event) => setRating(event.target.value)}/></label><div className="demo-value">{id === 'rate' ? '★'.repeat(Number(rating)) + '☆'.repeat(5 - Number(rating)) : `${rating} / 5`}</div></DemoShell>;
  if (['search', 'filter', 'sort'].includes(id)) { const rows = ['Design system', 'Project brief', 'User research']; const shown = rows.filter((row) => row.toLowerCase().includes(value.toLowerCase())); return <DemoShell title={english ? 'Find and filter' : '搜索与筛选'}><input className="demo-input" value={value} onChange={(event) => setValue(event.target.value)} placeholder={english ? 'Search projects…' : '搜索项目…'}/><div className="demo-list">{shown.map((row) => <button key={row} onClick={() => showNotice(`${row} ${english ? 'selected' : '已选择'}`)}>{row}<span>›</span></button>)}</div>{notice && <div className="demo-feedback success">✓ {notice}</div>}</DemoShell>; }
