function SourceReferences({ term, english }) {
  const references = term.referenceDetails?.references || [];
  const fallbackHrefs = term.id === 'git'
    ? ['https://git-scm.com/book/en/v2', 'https://git-scm.com/docs']
    : ['https://www.w3.org/WAI/ARIA/apg/patterns/button/', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Element/button'];
  const hrefFor = (reference, index) => term.id === 'api'
    ? 'https://developer.mozilla.org/en-US/docs/Glossary/API'
    : fallbackHrefs[index] || fallbackHrefs[fallbackHrefs.length - 1];
  const parseReference = (reference) => {
    const [title = reference, source = 'Reference ↗'] = reference.split('\n');
    return { title, source: source.replace(/\s*↗\s*$/, '') };
  };
  return <section className="references-section"><div className="section-title">{english ? 'Further reading' : '延伸阅读 · 权威出处'}</div><div className="reference-list">{references.map((reference, index) => { const item = parseReference(reference); return <a className="reference-link" key={reference} href={hrefFor(reference, index)} target="_blank" rel="noopener noreferrer"><span className="reference-title">{item.title}</span><span className="reference-source">{item.source} ↗</span></a>; })}</div></section>;
}

