function getAntiAiCatalog(english) { return english ? antiAiCatalog : antiAiCatalog.map((category) => ({ ...category, id: category.zhItems ? 'aif-category-zh' : category.id, items: category.zhItems || category.items })); }
function AifPreview({ item, english }) { return <div className={`aif-entry-preview aif-preview-${item.variant}`} aria-hidden="true"><span>{english ? item.en : item.zh}</span><p>{english ? item.example : (item.zhExample || '')}</p><i></i>{item.variant === 'three' && <div className="aif-preview-three-row"><i></i><i></i><i></i></div>}{item.variant === 'centered' && <div className="aif-preview-actions"><i></i><i></i></div>}</div>; }

function AntiAiPage({ english }) { usePageTitle(`${english ? 'Avoid AI Slop in UI and Copy' : '避免 AI 味儿'} | ${SITE.name}`); const scrollTo = (id) => document.getElementById(id)?.scrollIntoView({ behavior: 'smooth', block: 'start' }); return <main className="catalog-page aif-catalog-page"><div className="catalog-layout"><aside className="catalog-sidebar"><nav className="cat-chips" aria-label={english ? 'Avoid AI Slop' : '防止 AI 味儿'}>{antiAiCatalog.map((category) => <button type="button" key={category.id} onClick={() => scrollTo(category.id)}>{english ? category.enTitle : category.zhTitle}</button>)}</nav></aside><div className="grid-wrap"><header className="aif-catalog-heading"><p>AI slop field guide</p><h1>{english ? 'Avoid AI Slop' : '防止 AI 味儿'}</h1><div>{english ? 'Browse recurring writing tells, UI defaults, and UX shortcuts like glossary entries. Each entry includes examples, valid uses, and a concrete revision rule.' : '把常见的 AI 口癖、套模板的页面和不好用的交互当成词条来认。每条都给出例子、适用场景和具体改法。'}</div><small>{english ? 'One word, visual choice, or interaction bug cannot prove authorship. Judge repeated defaults in context.' : '一个词、一个视觉选择或一次交互问题都不能证明作者身份，要结合上下文判断重复出现的默认选择。'}</small></header>{antiAiCatalog.map((category) => <section className="cat-section" id={category.id} key={category.id}><div className="cat-title aif-cat-title"><div>{english ? category.enTitle : category.zhTitle}<small>{english ? category.enDesc : category.zhDesc}</small></div><span>{category.items.length} {english ? 'patterns' : '表现'}</span></div><div className="aif-card-grid">{category.items.map((item) => <article className="card aif-term-card" data-id={item.id} id={`aif-${item.id}`} key={item.id}><a href={`#aif-${item.id}`}><div className="card-head"><div className="card-title-group"><h3>{english ? item.en : item.zh}</h3></div></div><div className="card-tagline card-quote">{english ? item.quote : `遇到“${item.zh}”，把话说回真实任务，明确功能、状态和验证方式。`}</div><div className="card-demo"><AifPreview item={item}/></div></a></article>)}</div></section>)}</div></div></main>; }

function SkillCopyButton({ label, successLabel, copied, onClick }) {
  const ref = useRef(null);
  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const idle = el.querySelector('.skill-copy-idle');
    const success = el.querySelector('.skill-copy-success');
    if (idle) el.style.setProperty('--skill-copy-idle-width', idle.offsetWidth + 'px');
    if (success) el.style.setProperty('--skill-copy-success-width', success.offsetWidth + 'px');
  }, [label, successLabel]);
  return <button ref={ref} type="button" className={'skill-copy' + (copied ? ' is-copied' : '')} aria-label={label} onClick={onClick}><span className="skill-copy-state skill-copy-idle" aria-hidden="true"><i className="ti ti-copy"></i><span>{label}</span></span><span className="skill-copy-state skill-copy-success" aria-hidden="true"><i className="ti ti-check"></i><span>{successLabel}</span></span></button>;
}
