  const copyRewrite = async () => { const request = 'Add a Hover state and an Active state to the button, then use a Transition to make the visual change feel smooth.'; try { await navigator.clipboard.writeText(request); } catch {} setCopiedRewrite(true); window.setTimeout(() => setCopiedRewrite(false), 1600); };
