function ChangelogPage({ english }) {
  const [filter, setFilter] = useState('all');
  const [expanded, setExpanded] = useState({});
  usePageTitle(`${english ? 'Changelog' : '更新日志'} · ${SITE.name}`);
  useEffect(() => {
    const sidebar = document.querySelector('.changelog-sidebar');
    if (!sidebar) return undefined;
    const counts = sidebar.querySelectorAll('.changelog-sidebar-count');
    if (counts[0]) counts[0].textContent = '7';
    const monthLabels = sidebar.querySelectorAll('.changelog-sidebar-link > span:first-child');
    if (!english) ['2026 年 9 月', '2026 年 8 月', '2026 年 7 月'].forEach((value, index) => { if (monthLabels[index]) monthLabels[index].textContent = value; });
    if (!english) document.querySelectorAll('.changelog-terms-label').forEach((label) => { const textNodes = [...label.childNodes].filter((node) => node.nodeType === Node.TEXT_NODE); const number = textNodes.map((node) => node.textContent).join('').match(/\d+/)?.[0] || ''; textNodes.forEach((node) => { node.textContent = ''; }); if (textNodes[0]) textNodes[0].textContent = `收录新词汇（${number}）`; });
    const stats = sidebar.querySelectorAll('.changelog-stat-number');
    ['23', '354', '53+'].forEach((value, index) => { if (stats[index]) stats[index].textContent = value; });
    return undefined;
  }, [english, filter, expanded]);
  const prefix = english ? '/en' : '';
  const entryTerms = (entry) => entry.date === '2026-07-28' ? changelogBaselineTermIds : entry.termIds || [];
  const visible = changelogData.filter((entry) => filter !== 'terms' || entryTerms(entry)?.length);
  const dateLabel = (date) => { const [year, month, day] = date.split('-'); return english ? new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(date + 'T00:00:00Z')) : year + ' 年 ' + Number(month) + ' 月 ' + Number(day) + ' 日'; };
  const termInfo = (id) => {
    const detailEn = termBasics.en?.[id] || {};
    const detailZh = termBasics.zh?.[id] || {};
    const item = allItems.find((value) => itemFields(value).id === id);
    const englishTitle = detailEn.title || itemFields(item || [id, id]).name || id;
    const rawChinese = detailZh.title || extraZhNames[id] || englishTitle;
    const chineseTitle = rawChinese !== englishTitle && rawChinese.endsWith(englishTitle) ? rawChinese.slice(0, -englishTitle.length) : rawChinese;
    const section = allSections.find((value) => value.items.some((valueItem) => itemFields(valueItem).id === id));
    return { chineseTitle: chineseTitle || englishTitle, englishTitle, category: changelogCategoryOverrides[englishTitle] || changelogCategoryNames[section?.name] || section?.name || '', title: detailZh.tagline || detailEn.tagline || '' };
  };
  const scrollToMonth = (month) => { const target = [...document.querySelectorAll('.changelog-entry')].find((entry) => entry.id.startsWith(`changelog-${month}-`)); target?.scrollIntoView({ behavior: 'smooth', block: 'start' }); };
  return <div className="changelog-page-shell"><aside className="changelog-sidebar"><div className="changelog-sidebar-sticky"><div className="changelog-sidebar-section"><div className="changelog-sidebar-heading"><span className="changelog-sidebar-calendar" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="4" y="5" width="16" height="15" rx="2"/><path d="M8 3v4M16 3v4M4 10h16"/></svg></span><span>{english ? 'Timeline' : '时间定位'}</span></div><nav className="changelog-sidebar-nav" aria-label={english ? 'Changelog timeline' : '更新日志时间线'}>{[['2026-09', 'Sep 2026', '7'], ['2026-08', 'Aug 2026', '11'], ['2026-07', 'Jul 2026', '5']].map(([month, label, count]) => <button className="changelog-sidebar-link" type="button" key={month} onClick={() => scrollToMonth(month)}><span>{label}</span><span className="changelog-sidebar-count">{count}</span></button>)}</nav></div><div className="changelog-sidebar-stats"><div className="changelog-sidebar-stat"><span className="changelog-stat-number">23</span><span className="changelog-stat-label">{english ? 'Milestones' : '次重要迭代'}</span></div><div className="changelog-sidebar-stat"><span className="changelog-stat-number">354</span><span className="changelog-stat-label">{english ? 'Indexed Terms' : '个收录词汇'}</span></div><div className="changelog-sidebar-stat"><span className="changelog-stat-number">53+</span><span className="changelog-stat-label">{english ? 'Highlights' : '项功能改进'}</span></div></div></div></aside><main className="changelog-main-page"><nav className="changelog-breadcrumb" aria-label="Breadcrumb"><button className="changelog-breadcrumb-link" type="button" onClick={() => go(prefix || '/')}><ChangelogIcon name="arrow-left"/><span>{english ? 'All entries' : '术语图鉴'}</span></button><span className="changelog-breadcrumb-sep">/</span><span className="changelog-breadcrumb-current">{english ? 'Changelog' : '更新日志'}</span></nav><header className="changelog-header"><div className="changelog-header-main"><h1>{english ? 'Changelog' : '更新日志'}</h1><p className="changelog-subtitle">{english ? 'See new terms, courses, and features to help you learn.' : '看看新增了哪些词条、学习路线和实用功能。'}</p></div><div className="changelog-filter-group" data-filter={filter} role="group" aria-label={english ? 'Changelog filters' : '更新日志筛选'}><span className="changelog-filter-indicator" aria-hidden="true"/>{[['all', english ? 'All' : '全部'], ['updates', english ? 'Updates' : '功能更新'], ['terms', english ? 'New Terms' : '新增词汇']].map(([value, label]) => <button key={value} className={filter === value ? 'changelog-filter-btn is-active' : 'changelog-filter-btn'} type="button" onClick={() => setFilter(value)}>{label}</button>)}</div></header><section className="changelog-timeline">{visible.map((entry) => { const entryIndex = changelogData.indexOf(entry); const allTerms = entryTerms(entry) || []; const terms = expanded[entry.date] ? allTerms : allTerms.slice(0, 12); const iconNames = changelogIconRows[entryIndex] || []; return <article className="changelog-entry" id={`changelog-${entry.date}`} key={entry.date}><div className="changelog-entry-meta"><span className="changelog-track-node" aria-hidden="true"/><time className="changelog-entry-date">{dateLabel(entry.date)}</time>{entry.version && <span className="changelog-version-badge">{entry.version}</span>}</div><div className="changelog-entry-body"><header className="changelog-milestone"><h2 className="changelog-milestone-title">{english ? entry.title : entry.titleZh}</h2>{(english ? entry.summary : entry.summaryZh) && <p className="changelog-milestone-summary">{english ? entry.summary : entry.summaryZh}</p>}</header><div className="changelog-group changelog-updates-group"><ul className="changelog-items-list">{getChangelogItems(entry, english).map((item, itemIndex) => <li className="changelog-item" key={`${entry.date}-${item}`}><span className="changelog-item-icon">{<ChangelogIcon name={iconNames[itemIndex] || 'check'}/>}</span><span className="changelog-item-text">{item}</span></li>)}</ul></div>{allTerms.length ? <div className="changelog-group changelog-terms-group"><div className="changelog-terms-heading"><span className="changelog-terms-label"><span className="changelog-books-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M5 5.5A2.5 2.5 0 0 1 7.5 3H20v15H7.5A2.5 2.5 0 0 0 5 20.5v-15ZM5 5.5v15"/><path d="M8.5 7H16M8.5 11H16"/></svg></span>{english ? 'New Terms' : '新增词汇'} ({allTerms.length})</span></div><div className="changelog-terms-grid">{terms.map((id) => { const term = termInfo(id); return <SmartLink className="changelog-term-pill" href={`${prefix}/${id}`} key={id} title={term.title}><span className="changelog-term-cn">{term.chineseTitle}</span><span className="changelog-term-en">{term.englishTitle}</span><span className="changelog-term-cat">{term.category}</span></SmartLink>; })}</div>{allTerms.length > terms.length && <button className="changelog-expand-btn" type="button" onClick={() => setExpanded((current) => ({ ...current, [entry.date]: true }))}>{english ? `Show all ${allTerms.length} terms` : `展开全部 ${allTerms.length} 个词条`}</button>}</div> : null}</div></article>; })}</section></main></div>;
}

